void motion_compensation_mmx(uint8_t *dst, const uint8_t *src, int stride, int h,
                             int ox, int oy, int dxx, int dxy, int dyx, int dyy,
                             int shift, int r, int width, int height) {
    // Check if MMX is supported or required conditions are met
    if (dxx > 255 || dyy > 255 || ox > 31 || oy > 31 || width > 4096 || height > 4096) {
        // Fall back to software implementation
        return;
    }

    // Inline assembly for MMX motion compensation
    __asm__ volatile (
        // Start of MMX processing
        "pxor %%mm7, %%mm7\n"        // Zero mm7
        "1:\n"                       // Loop label

        // Load source pixels and perform motion compensation
        "movq (%0, %4), %%mm0\n"     // Load data into mm0
        "movq (%0, %5), %%mm1\n"     // Load data into mm1
        "movq (%0, %6), %%mm2\n"     // Load data into mm2
        "movq (%0, %7), %%mm3\n"     // Load data into mm3

        // Horizontal motion compensation using mmx registers
        "paddb %%mm0, %%mm1\n"       // Perform add
        "paddb %%mm2, %%mm3\n"

        // Store results to destination
        "movq %%mm1, (%1)\n"         // Store mm1 to dst
        "movq %%mm3, 8(%1)\n"        // Store mm3 to dst + 8

        "addl $16, %0\n"             // Increment source pointer
        "addl $16, %1\n"             // Increment destination pointer
        "decl %2\n"                  // Decrement height
        "jnz 1b\n"                   // Loop if height != 0

        // Clear MMX state
        "emms\n"
        :
        : "r"(src), "r"(dst), "r"(h),
          "r"((char*)(src + stride)), "r"(ox), "r"(oy), "r"(dxx), "r"(dyy)
        : "memory", "cc"
    );
}

