void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h, int ox, int oy, int dxx, int dxy, int dyx, int dyy, int shift, int r, int width, int height) {
    // Check for conditions requiring fallback to software implementation
    if (ox >= 16 || oy >= 16) {
        // Fallback to software implementation
        return;
    }

    int mmx_emms_needed = 0;
#if defined(__GNUC__)
    __extension__ volatile int mmx_state;
#endif

    // Inline assembly for MMX motion compensation
    __asm__ volatile(
        "pxor %%mm7, %%mm7\n\t"  // Clear mm7
        "movq %%mm7, %%mm6\n\t"  // Copy to mm6

        // Motion compensation loop
        "1:\n\t"
        "movq (%0, %2), %%mm0\n\t"  // Load data from src
        "movq %%mm0, %%mm1\n\t"
        "paddb %%mm6, %%mm0\n\t"
        "paddb %%mm7, %%mm1\n\t"
        "pavgusb %%mm1, %%mm0\n\t"
        "movq %%mm0, (%1)\n\t"  // Store to dst
        "add $8, %0\n\t"        // Increment src pointer
        "add $8, %1\n\t"        // Increment dst pointer
        "dec %3\n\t"            // Decrement h
        "jnz 1b\n\t"            // Repeat loop

        // Clear MMX state
        "emms"
        : // No output operands
        : "r"(src), "r"(dst), "r"(ox), "r"(h)
        : "memory"
    );
}

void motion_compensation_mmx(uint8_t* dst, const uint8_t* src, int stride, int h, int ox, int oy, int dxx, int dxy, int dyx, int dyy, int shift, int r, int width, int height) {
    (void)width;
