    if ((dxx >= 8) || (dxx <= -8) || (dxy >= 8) || (dxy <= -8) ||
        (dyx >= 8) || (dyx <= -8) || (dyy >= 8) || (dyy <= -8)) {
        // Software fallback
        return;
    }

    __asm__ volatile (
        "pusha\n"
        "movq %1, %%mm0\n"
        "movq %2, %%mm1\n"
        "movq %3, %%mm2\n"
        "movq %4, %%mm3\n"
        "movq %5, %%mm4\n"
        "movq %6, %%mm5\n"
        "movq %7, %%mm6\n"
        "movq %8, %%mm7\n"
        "emms\n"
        "popa\n"
        :
        : "m"(dxx), "m"(dxy), "m"(dyx), "m"(dyy),
          "m"(ox), "m"(oy), "m"(shift), "m"(h)
        : "memory"
    );
